mapper.insert:
INSERT INTO file_cleanup_task (
task_type,
source_path,
destination_path
)
VALUES (
#{taskType},
#{sourcePath},
#{destinationPath}
)

mapper.update:
UPDATE file_cleanup_task
SET attempts = attempts + 1,
    next_attempt_at = DATE_ADD(
        CURRENT_TIMESTAMP,
        INTERVAL #{retryDelaySeconds} SECOND
),
last_error = #{lastError}
WHERE id = #{taskId}
